from pathlib import Path
import json,hashlib,html
R=Path(__file__).resolve().parents[1];W=Path('./.local/station-realism');C=W/'central-gate-hardware-05';O=R/'notes/central-gate-hardware';O.mkdir(exist_ok=True)
files={n:C/n for n in ['report.json','serialization.json','normals.json','spatial-proof.json']};files['spec.json']=W/'central-gate-hardware-spec-01/spec.json'
for view in ['front','close','rear']:
 files[view+'.png']=C/view/'source.png';files[view+'-receipt.json']=C/view/'projection.json'
manifest=[]
for name,p in files.items():
 b=p.read_bytes();(O/name).write_bytes(b);manifest.append({'file':name,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)})
(O/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
figures=''.join(f'<figure><a href="{v}.png"><img src="{v}.png" alt="Gate hardware {v} inspection"></a><figcaption>{label}. Fixed local inspection camera; studio lighting, no photographic alignment.</figcaption></figure>' for v,label in [('front','Three-body sample and two lane widths'),('close','Rounded paddle, reader, ticket mouth and side panels'),('rear','Reader and exit-facing indicators')])
links=''.join(f'<li><a href="{n}">{n}</a></li>' for n in files if n.endswith('.json'))
(O/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central gate hardware prototype</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f2ec;color:#24382f;font:16px/1.55 system-ui}main{max-width:1200px;margin:auto;padding:24px}h1{line-height:1.15}a{color:#17654c;overflow-wrap:anywhere}figure{margin:24px 0}img{width:100%;display:block}figcaption{background:#e1e8df;padding:12px;font-size:14px}.status{padding:18px;background:#f2dfb4}li{margin:8px 0}</style><main><a href="../../index.html">Research library</a><h1>Central gate hardware: original component</h1><p>28 September 2026. The prototype now includes curved covers, blue reader trim, exposed card pads, ticket slots, service-panel seams, rounded flaps and directional indicators.</p><p class="status">Uninstalled prototype. Comparable manufacturer dimensions are provisional for Kyoto. The actual gate model, lane count and station placement remain unverified. Materials and lighting are initial samples; this is not a photorealism or performance acceptance result.</p><p>Three bodies demonstrate a nominal 600mm standard lane and 900mm wide lane. The central sample flaps are closed; the wide lane is clear. Body dimensions use the comparable GX-7 drawing: 1600mm length, 1000mm height and 175mm width. Fine details are inferred from the Kyoto photographs.</p><p>7,576 triangles, eight material batches, no image textures, 204 component records and 14 colliding solids. Browser/native coordinates and winding agree exactly; closed meshes and face normals pass. Nineteen static geometry probes check body surfaces, paddle obstruction, wide-lane clearance and exposed readers. These are geometry checks, not native runtime proofs.</p>'''+figures+'''<h2>Evidence and remaining work</h2><p><a href="../CENTRAL-GATE-HARDWARE.md">Construction note</a> · <a href="../central-gate-registration/index.html">Dated Kyoto references and registration limits</a> · <a href="../../plans/gate-nippon-gx7-drawing.pdf">Manufacturer drawing, PDF page 4</a></p><p>Before installation: confirm equipment identity, register the full portal/bridge/barrier line, establish the lane count and approach, improve material response in the station lighting, then run placement and gameplay checks. The three-body sample is not an inferred station census.</p><ul>'''+links+'''<li><a href="manifest.json">Evidence hashes</a></li></ul></main></html>''')
print(O)
